function (eng, ctx) {
  // eng = recipe 下发的本参数工程值;返回真实写请求(多字段 API 只写本节点负责的一个字段)
  return { method: 'POST', path: '/api/v1/params/multi/set', body: { tem: eng } }
}

function (param, ctx) {
  // param = {status, reply(MES 响应 JSON), eng(本次设定)};返回 {ok, message}
  return { ok: !!(param.reply && param.reply.applied && param.reply.applied.tem === param.eng), message: 'applied.tem === 设定值' }
}

function (param, ctx) {
  // param = Agent 传入的参数对象;返回请求覆盖(合入映射声明,钩子优先)
  return { query: { from: param.from, to: param.to, lane: param.lane } }
}

function (param, data, ctx) {
  // data.rows = 格式化行(标量 value/向量 values/图像 data+mime/记录 record);data.node = 点位信息
  const means = data.rows.map(r => r.values.reduce((a, b) => a + b, 0) / r.values.length)
  ctx.plot({ name: 'trend', title: data.node.name, series: [{ name: 'rowMean', points: means.map((v, i) => [i, v]) }] })
  ctx.saveCsv({ name: 'rows', rows: [['ts', 'mean']].concat(data.rows.map(r => [r.ts, r.values[0]])) })
  return { summary: `行数 ${data.rows.length},均值 ${means[0].toFixed(2)}`, context: '已绘图并存 CSV' }
}
